@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Mono:wght@400;500&family=Inter:wght@400;500;600;700&display=swap');
:root{--lime:#d2f46b;--ink:#101513;--panel:rgba(13,19,17,.8);--line:rgba(232,245,222,.16);--muted:#91a096;--white:#eff3ea}
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#101513;color:var(--white);font-family:Inter,Arial,sans-serif;user-select:none;-webkit-user-select:none;touch-action:none}button{font:inherit;color:inherit}#game-shell{position:relative;width:100vw;height:100dvh;overflow:hidden;background:#26302c}#view{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at center,transparent 42%,rgba(5,9,7,.22) 100%);box-shadow:inset 0 0 100px rgba(0,0,0,.32)}
.topbar{height:62px;position:absolute;z-index:2;top:0;left:0;right:0;display:flex;align-items:center;padding:0 30px;background:linear-gradient(180deg,rgba(8,13,11,.86),rgba(8,13,11,.2));border-bottom:1px solid rgba(255,255,255,.1);gap:30px}.brand{display:flex;align-items:center;gap:10px;font-size:13px;font-weight:800;letter-spacing:2px}.brand-mark{display:grid;place-items:center;width:27px;height:29px;background:var(--lime);color:#182018;font-family:'Barlow Condensed';font-weight:900;font-size:20px;clip-path:polygon(0 0,100% 0,100% 78%,50% 100%,0 78%)}.brand-sub{font-size:10px;letter-spacing:1.2px;color:#a6b0a7;font-weight:500}.objective{height:26px;display:flex;align-items:center;gap:9px;padding:0 11px;border:1px solid rgba(210,244,107,.35);background:rgba(210,244,107,.08);font:10px 'DM Mono',monospace;letter-spacing:1px;color:#e3f8b1}.objective i{width:7px;height:7px;background:var(--lime);border-radius:50%;box-shadow:0 0 10px var(--lime);animation:pulse 1.5s infinite}.round-label{margin-left:auto;font:10px 'DM Mono',monospace;letter-spacing:1px;color:#aab4ab}.round-label b{color:var(--lime)}.round-label span{color:#e5e9e1}@keyframes pulse{50%{opacity:.42}}
.hud{position:absolute;z-index:2;top:79px;left:28px;right:28px;display:flex;justify-content:space-between;align-items:flex-start;pointer-events:none}.left-hud{display:flex;flex-direction:column;gap:8px}.map-wrap{width:154px;height:166px;padding:5px;background:rgba(10,15,13,.75);border:1px solid var(--line);box-shadow:0 5px 25px #0005}.map-wrap canvas{width:142px;height:142px;display:block;image-rendering:pixelated}.map-caption{display:flex;justify-content:space-between;padding:5px 3px 0;font:8px 'DM Mono',monospace;letter-spacing:.8px;color:#a9b5aa}.map-caption b{color:var(--lime)}.team-status{display:flex;align-items:center;gap:8px;font:9px 'DM Mono',monospace;color:#c5cec5;letter-spacing:.7px;padding:8px 10px;background:var(--panel);border:1px solid var(--line)}.team-status b{margin-left:auto;color:var(--lime);font-weight:500}.status-dot{width:6px;height:6px;background:var(--lime);border-radius:50%}.center-hud{position:absolute;top:3px;left:50%;transform:translateX(-50%);text-align:center}.timer-box{padding:9px 18px 8px;min-width:162px;background:rgba(12,17,15,.74);border:1px solid var(--line);clip-path:polygon(8px 0,100% 0,100% calc(100% - 8px),calc(100% - 8px) 100%,0 100%,0 8px)}.timer-box span{display:block;color:#a1ada2;font:8px 'DM Mono',monospace;letter-spacing:1.2px}.timer-box b{display:block;margin-top:3px;font:700 25px 'Barlow Condensed',sans-serif;letter-spacing:2px;color:#f1f3eb}.timer-box.urgent b{color:#ff735d}.progress-wrap{display:none;margin:8px auto 0;width:130px;color:var(--lime);font:8px 'DM Mono',monospace;letter-spacing:1px}.progress-wrap.active{display:block}.progress-wrap:before{content:'';display:block;height:3px;background:#ffffff30;margin-bottom:5px}.progress-wrap div{position:relative;height:3px;background:var(--lime);margin-bottom:-3px;width:0}.right-hud{display:flex;align-items:center;gap:12px;padding:11px 13px;background:var(--panel);border:1px solid var(--line)}.ammo>span{display:block;color:#9eaaa0;font:8px 'DM Mono',monospace;letter-spacing:1px}.ammo>span b{color:#dce7dc;font-weight:500}.ammo strong{display:block;font:700 27px 'Barlow Condensed';letter-spacing:1px}.ammo strong span{font-size:14px;color:#9eaaa0}.weapon-icon{font-size:29px;color:var(--lime);transform:rotate(-30deg);padding-left:12px;border-left:1px solid var(--line)}
.crosshair{position:absolute;z-index:3;left:50%;top:50%;width:18px;height:18px;transform:translate(-50%,-50%);pointer-events:none;filter:drop-shadow(0 1px 2px #111)}.crosshair i{position:absolute;display:block;background:rgba(234,245,227,.95)}.crosshair i:nth-child(1){width:1px;height:5px;left:8px;top:0}.crosshair i:nth-child(2){width:1px;height:5px;left:8px;bottom:0}.crosshair i:nth-child(3){height:1px;width:5px;left:0;top:8px}.crosshair i:nth-child(4){height:1px;width:5px;right:0;top:8px}.crosshair b{position:absolute;width:2px;height:2px;background:var(--lime);left:8px;top:8px;border-radius:50%}.hit-marker{position:absolute;z-index:4;left:50%;top:50%;transform:translate(-50%,-50%);font:700 28px 'Barlow Condensed';color:white;text-shadow:0 0 6px var(--lime);opacity:0;pointer-events:none}.hit-marker.show{animation:hit .22s ease-out}@keyframes hit{0%{opacity:1;transform:translate(-50%,-50%) scale(.6)}100%{opacity:0;transform:translate(-50%,-50%) scale(1.3)}}.toast{position:absolute;z-index:3;top:60%;left:50%;transform:translate(-50%,0);font:10px 'DM Mono',monospace;letter-spacing:1px;color:#f5f4e8;background:rgba(11,17,14,.82);padding:9px 15px;border:1px solid #ffffff25;opacity:0;transition:opacity .2s;white-space:nowrap}.toast.show{opacity:1}
.bottom-hud{position:absolute;z-index:2;left:30px;right:30px;bottom:24px;display:flex;align-items:flex-end;justify-content:space-between;pointer-events:none}.health,.armor{display:flex;align-items:center;gap:9px;padding:9px 12px;background:var(--panel);border:1px solid var(--line);min-width:140px}.health-icon{font-size:19px;color:var(--lime)}.armor-icon{font-size:17px;color:#9db6d2}.health>div:nth-child(2),.armor>div{display:flex;flex-direction:column}.health b,.armor b{font:700 21px 'Barlow Condensed';line-height:20px}.health small,.armor small{font:7px 'DM Mono';letter-spacing:1px;color:#a7b3a8}.health-bar{height:3px;width:35px;background:#ffffff28;margin-left:auto}.health-bar i{display:block;height:100%;width:100%;background:var(--lime)}.controls-hint{align-self:center;color:#c3cbc3;font:8px 'DM Mono',monospace;letter-spacing:1px;text-shadow:0 1px 3px #000}.controls-hint span{padding:4px 5px;margin:0 4px;background:#111b18bd;border:1px solid #ffffff30;color:var(--lime);font-size:8px}
.screen{position:absolute;z-index:10;inset:0;display:flex;align-items:center;justify-content:center;background:linear-gradient(90deg,rgba(9,14,12,.91) 0%,rgba(9,14,12,.7) 43%,rgba(9,14,12,.18) 100%);opacity:0;visibility:hidden;transition:opacity .3s,visibility .3s}.screen.visible{opacity:1;visibility:visible}.intro-card{width:min(440px,calc(100vw - 42px));margin-left:-32vw;padding:36px 38px;background:rgba(12,18,16,.91);border:1px solid rgba(225,237,221,.18);box-shadow:0 22px 80px #0008;position:relative}.intro-card:before{content:'';position:absolute;left:-1px;top:0;height:65px;width:3px;background:var(--lime)}.eyebrow{font:9px 'DM Mono',monospace;letter-spacing:1.5px;color:#bac4b9;display:flex;align-items:center;gap:8px}.eyebrow span{width:6px;height:6px;border-radius:50%;background:var(--lime);box-shadow:0 0 8px var(--lime)}h1{font:800 clamp(43px,5vw,62px)/.86 'Barlow Condensed',Impact,sans-serif;letter-spacing:1px;margin:22px 0 17px;color:#f2f4ed}h1 em{font-style:normal;color:var(--lime)}.intro-card p{max-width:350px;color:#aab5ac;font-size:12px;line-height:1.7;margin:0 0 23px}.mission-facts{display:flex;padding:13px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);gap:15px}.mission-facts div{display:flex;flex:1;flex-direction:column;gap:5px;min-width:0}.mission-facts small{color:#829087;font:8px 'DM Mono';letter-spacing:1px}.mission-facts b{font:600 9px 'DM Mono';letter-spacing:.3px;white-space:nowrap;color:#e2e8de}.primary-button{display:flex;align-items:center;justify-content:space-between;width:100%;margin-top:22px;padding:14px 16px;border:0;background:var(--lime);color:#172017;font:800 13px 'Barlow Condensed';letter-spacing:1.7px;cursor:pointer;transition:background .15s,transform .15s}.primary-button:hover{background:#e2ff88;transform:translateY(-1px)}.primary-button span{font-size:18px}.input-note{font:8px/1.9 'DM Mono';letter-spacing:.4px;color:#87938a;margin-top:17px}.input-note b{color:#dce7d9;font-weight:500}.screen-footer{position:absolute;bottom:20px;left:28px;font:8px 'DM Mono';letter-spacing:1.1px;color:#7f8a80}.screen-footer span{color:var(--lime);margin:0 8px}.end-card{margin-left:0}.end-card h1{font-size:58px}.end-card p{margin-bottom:20px}
#touch-controls{display:none}.touch-button{border:1px solid #e6f4dd77;color:white;background:rgba(14,22,18,.64);backdrop-filter:blur(8px);border-radius:50%;width:68px;height:68px;font:700 11px 'DM Mono';letter-spacing:.8px;touch-action:none}.fire-button{border:2px solid rgba(210,244,107,.8);background:rgba(137,164,76,.32);box-shadow:0 0 22px #bde95d25;color:#efffc6}.reload-button{width:48px;height:48px;font-size:23px}.use-button{display:none;border-radius:3px;width:102px;height:40px;color:var(--lime);border-color:#d2f46b88}.use-button.available{display:block}.use-button.pressed{background:#c9ef5b55}.#stick-zone{position:absolute;width:126px;height:126px;left:21px;bottom:22px;border-radius:50%;background:#101a1780;border:1px solid #ffffff22;touch-action:none}#stick{position:absolute;width:56px;height:56px;left:34px;top:34px;border-radius:50%;background:#d2f46b55;border:1px solid #e7f8c48a;box-shadow:0 2px 12px #0005;display:grid;place-items:center}#stick span{width:6px;height:6px;border-radius:50%;background:#e7f8c4}
@media (pointer:coarse){#touch-controls{display:block}.controls-hint{display:none}.bottom-hud{left:16px;right:16px;bottom:13px}.health,.armor{min-width:102px;padding:7px 9px}.health-bar{width:20px}.health b,.armor b{font-size:18px}.hud{top:70px;left:14px;right:14px}.map-wrap{width:124px;height:135px;padding:4px}.map-wrap canvas{width:114px;height:114px}.map-caption{font-size:7px}.team-status{padding:6px 8px;font-size:8px}.right-hud{padding:8px}.ammo strong{font-size:23px}.center-hud{top:0}.timer-box{min-width:130px;padding:7px 12px}.timer-box b{font-size:22px}.topbar{height:49px;padding:0 14px;gap:10px}.brand{font-size:11px;gap:7px}.brand-mark{width:22px;height:24px;font-size:16px}.brand-sub{font-size:8px}.objective{height:23px;padding:0 7px;font-size:8px}.round-label{display:none}.intro-card{margin-left:0;padding:27px 25px;width:min(410px,calc(100vw - 35px))}.screen{background:rgba(8,13,11,.77)}.intro-card h1{font-size:50px}.screen-footer{left:14px;bottom:8px;font-size:7px}}
@media (max-width:650px){.right-hud{gap:7px}.weapon-icon{display:none}.map-wrap{opacity:.9}.center-hud{left:55%}.bottom-hud{bottom:158px}.health,.armor{background:rgba(10,15,13,.5)}#stick-zone{width:114px;height:114px;left:17px;bottom:18px}#stick{left:29px;top:29px}.fire-button{position:absolute;right:22px;bottom:32px;width:76px;height:76px}.reload-button{position:absolute;right:105px;bottom:26px}.use-button{position:absolute;right:25px;bottom:120px}.end-card{margin:0}}
@media (max-height:520px) and (pointer:coarse){.topbar{height:42px}.hud{top:51px}.map-wrap{display:none}.team-status{display:none}.bottom-hud{bottom:8px}.health,.armor{padding:4px 7px}.fire-button{bottom:18px;width:62px;height:62px}.reload-button{bottom:13px}.use-button{bottom:88px}#stick-zone{bottom:10px;width:100px;height:100px}#stick{left:25px;top:25px}.intro-card{padding:18px 24px}.intro-card h1{font-size:42px;margin:12px 0}.intro-card p{margin-bottom:12px}.mission-facts{padding:8px 0}.primary-button{margin-top:12px;padding:10px}.input-note{margin-top:9px}}

(() => {
  const canvas = document.getElementById('view'), ctx = canvas.getContext('2d');
  const mapCanvas = document.getElementById('map'), mctx = mapCanvas.getContext('2d');
  const W = 16, H = 16, FOV = Math.PI * .39, TAU = Math.PI * 2;
  const world = Array.from({length:H}, (_,y) => Array.from({length:W}, (_,x) => (x===0||y===0||x===W-1||y===H-1)?1:0));
  // Low concrete cover and two offset walls create a compact, readable arena.
  [[5,3],[5,4],[5,5],[5,6],[9,3],[10,3],[11,3],[11,4],[3,8],[4,8],[5,8],[10,7],[10,8],[10,9],[7,11],[8,11],[9,11],[12,7],[12,8]].forEach(([x,y])=>world[y][x]=1);
  const ui = id => document.getElementById(id);
  const player = {x:2.5,y:2.5,a:.2,hp:100,armor:100,ammo:24,reserve:96,kills:0};
  const bomb = {x:8.55,y:8.55,defused:false,progress:0};
  const enemies = [
    {x:12.5,y:5.5,hp:100,alive:true,cool:1.2,phase:0},
    {x:7.5,y:7.5,hp:100,alive:true,cool:2.1,phase:1.7},
    {x:12.5,y:12.5,hp:100,alive:true,cool:.8,phase:3.2}
  ];
  let running=false,ended=false,last=0,elapsed=0,timeLeft=75,fireHeld=false,fireCooldown=0,toastTimer=0,damageFlash=0,moveInput={x:0,y:0},lookInput=0,keys={},drag=null,defuseKey=false,damagePulse=0;
  let width=0,height=0,dpr=1,depths=[],lastShot=0;
  const low=document.createElement('canvas'), lctx=low.getContext('2d'); low.width=480; low.height=270;
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
  const norm=a=>{while(a>Math.PI)a-=TAU;while(a< -Math.PI)a+=TAU;return a};
  function resize(){dpr=Math.min(devicePixelRatio||1,1.7);width=innerWidth;height=innerHeight;canvas.width=Math.floor(width*dpr);canvas.height=Math.floor(height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}
  addEventListener('resize',resize);resize();
  function blocked(x,y){return x<.2||y<.2||x>W-.2||y>H-.2||world[Math.floor(y)]?.[Math.floor(x)]!==0}
  function lineOfSight(x1,y1,x2,y2){let dx=x2-x1,dy=y2-y1,n=Math.ceil(Math.hypot(dx,dy)*8);for(let i=1;i<n;i++){let x=x1+dx*i/n,y=y1+dy*i/n;if(world[Math.floor(y)]?.[Math.floor(x)])return false}return true}
  function ray(angle){const dx=Math.cos(angle),dy=Math.sin(angle);let mx=Math.floor(player.x),my=Math.floor(player.y),ddx=Math.abs(1/(dx||1e-9)),ddy=Math.abs(1/(dy||1e-9)),sx,sy,sdx,sdy,side=0;if(dx<0){sx=-1;sdx=(player.x-mx)*ddx}else{sx=1;sdx=(mx+1-player.x)*ddx}if(dy<0){sy=-1;sdy=(player.y-my)*ddy}else{sy=1;sdy=(my+1-player.y)*ddy}let steps=0;while(steps++<64){if(sdx<sdy){sdx+=ddx;mx+=sx;side=0}else{sdy+=ddy;my+=sy;side=1}if(world[my]?.[mx])break}let d=side?(my-player.y+(1-sy)/2)/(dy||1e-9):(mx-player.x+(1-sx)/2)/(dx||1e-9);return {d:Math.max(.05,d),side,wallX:side?player.x+d*dx:player.y+d*dy}}
  function showToast(text){const t=ui('toast');t.textContent=text;t.classList.add('show');toastTimer=1.5}
  function start(){player.x=2.5;player.y=2.5;player.a=.2;player.hp=100;player.armor=100;player.ammo=24;player.reserve=96;player.kills=0;bomb.defused=false;bomb.progress=0;enemies.forEach((e,i)=>Object.assign(e,{alive:true,hp:100,cool:1.1+i*.7}));timeLeft=75;elapsed=0;ended=false;running=true;ui('start-screen').classList.remove('visible');ui('end-screen').classList.remove('visible');ui('objective-text').textContent='DEFUSE THE DEVICE';last=performance.now();requestAnimationFrame(loop);}
  ui('start-button').addEventListener('click',start);ui('again-button').addEventListener('click',start);
  function endGame(win){if(ended)return;ended=true;running=false;ui('result-title').innerHTML=win?'SITE<br><em>SECURED.</em>':'MISSION<br><em>FAILED.</em>';ui('result-copy').textContent=win?'Device defused. Site Echo is secure.':'The device detonated or your squad was eliminated.';ui('result-kills').textContent=`${player.kills} / 3`;ui('result-health').textContent=`${player.hp}%`;ui('result-status').textContent=win?'SUCCESS':'FAILED';ui('end-screen').classList.add('visible')}
  function reload(){if(!running||player.ammo===24||player.reserve<=0)return;const need=24-player.ammo,n=Math.min(need,player.reserve);player.ammo+=n;player.reserve-=n;showToast('MAGAZINE RELOADED')}
  addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='KeyR')reload();if(e.code==='KeyE')defuseKey=true;if(e.code==='Space')fireHeld=true});
  addEventListener('keyup',e=>{keys[e.code]=false;if(e.code==='KeyE')defuseKey=false;if(e.code==='Space')fireHeld=false});
  canvas.addEventListener('click',()=>{if(running)fireHeld=true});canvas.addEventListener('contextmenu',e=>e.preventDefault());
  addEventListener('mouseup',()=>fireHeld=false);
  canvas.addEventListener('mousemove',e=>{if(running&&e.buttons===2)player.a+=e.movementX*.0035});
  const stickZone=ui('stick-zone'), stick=ui('stick');let stickId=null;
  stickZone.addEventListener('pointerdown',e=>{stickId=e.pointerId;stickZone.setPointerCapture(stickId);updateStick(e)});
  stickZone.addEventListener('pointermove',e=>{if(e.pointerId===stickId)updateStick(e)});
  stickZone.addEventListener('pointerup',e=>{if(e.pointerId===stickId){stickId=null;moveInput={x:0,y:0};stick.style.transform='translate(0px,0px)'}});
  function updateStick(e){const r=stickZone.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=e.clientX-cx,dy=e.clientY-cy,len=Math.hypot(dx,dy),max=39,k=len>max?max/len:1;moveInput={x:dx*k/max,y:dy*k/max};stick.style.transform=`translate(${dx*k}px,${dy*k}px)`}
  const fireButton=ui('fire-button');fireButton.addEventListener('pointerdown',e=>{e.preventDefault();fireHeld=true;fireButton.setPointerCapture(e.pointerId)});fireButton.addEventListener('pointerup',()=>fireHeld=false);fireButton.addEventListener('pointercancel',()=>fireHeld=false);
  ui('reload-button').addEventListener('pointerdown',e=>{e.preventDefault();reload()});
  const useButton=ui('use-button');useButton.addEventListener('pointerdown',e=>{e.preventDefault();defuseKey=true;useButton.classList.add('pressed')});for(const ev of ['pointerup','pointercancel','lostpointercapture'])useButton.addEventListener(ev,()=>{defuseKey=false;useButton.classList.remove('pressed')});
  canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='touch'&&running&&e.clientX>width*.34){drag={id:e.pointerId,x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId)}});
  canvas.addEventListener('pointermove',e=>{if(drag&&e.pointerId===drag.id){player.a+=(e.clientX-drag.x)*.006;drag.x=e.clientX;drag.y=e.clientY}});
  canvas.addEventListener('pointerup',e=>{if(drag?.id===e.pointerId)drag=null});canvas.addEventListener('pointercancel',()=>drag=null);
  function shoot(){if(player.ammo<=0){showToast('MAGAZINE EMPTY · TAP ↻ TO RELOAD');fireCooldown=.32;return}player.ammo--;fireCooldown=.19;damagePulse=.09;let target=null,best=.09;for(const e of enemies){if(!e.alive)continue;const dx=e.x-player.x,dy=e.y-player.y,d=Math.hypot(dx,dy),err=Math.abs(norm(Math.atan2(dy,dx)-player.a));const allowance=Math.max(.035,.13/d);if(err<allowance&&d<13&&d<ray(player.a).d+.15&&err<best){best=err;target=e}}if(target){target.hp-=48;const h=ui('hit-marker');h.classList.remove('show');void h.offsetWidth;h.classList.add('show');if(target.hp<=0){target.alive=false;player.kills++;showToast('HOSTILE NEUTRALIZED')}}}
  function update(dt){elapsed+=dt;timeLeft=Math.max(0,timeLeft-dt);fireCooldown=Math.max(0,fireCooldown-dt);damageFlash=Math.max(0,damageFlash-dt);damagePulse=Math.max(0,damagePulse-dt);toastTimer-=dt;if(toastTimer<=0)ui('toast').classList.remove('show');player.a=norm(player.a);
    const forward=(keys.KeyW||keys.ArrowUp?-1:0)+(keys.KeyS||keys.ArrowDown?1:0)-moveInput.y,strafe=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+moveInput.x,turn=(keys.KeyQ?-1:0)+(keys.KeyE&&!defuseKey?1:0);player.a=norm(player.a+turn*dt*1.9+lookInput);lookInput=0;const len=Math.hypot(forward,strafe)||1,speed=(keys.ShiftLeft||keys.ShiftRight?3.5:2.65)*dt;const vx=(Math.cos(player.a)*-forward+Math.cos(player.a+Math.PI/2)*strafe)/len*speed,vy=(Math.sin(player.a)*-forward+Math.sin(player.a+Math.PI/2)*strafe)/len*speed;if(!blocked(player.x+vx,player.y))player.x+=vx;if(!blocked(player.x,player.y+vy))player.y+=vy;
