  function drawMap(){const c=mctx,s=mapCanvas.width/W;c.clearRect(0,0,144,144);c.fillStyle='#111916';c.fillRect(0,0,144,144);for(let y=0;y<H;y++)for(let x=0;x<W;x++){c.fillStyle=world[y][x]?'#738076':'#2b3630';c.fillRect(x*s,y*s,s-1,s-1)}if(!bomb.defused){c.fillStyle='#d2f46b';c.fillRect(bomb.x*s-2,bomb.y*s-2,4,4)}for(const e of enemies)if(e.alive){c.fillStyle='#e07c62';c.beginPath();c.arc(e.x*s,e.y*s,2.4,0,TAU);c.fill()}c.fillStyle='#eff5e4';c.beginPath();c.arc(player.x*s,player.y*s,3.2,0,TAU);c.fill();c.strokeStyle='#d2f46b';c.beginPath();c.moveTo(player.x*s,player.y*s);c.lineTo((player.x+Math.cos(player.a)*1.6)*s,(player.y+Math.sin(player.a)*1.6)*s);c.stroke()}
